Here is the TypeScript function:

export function getAwsAccountId(arn: string): string | null {
  const parts = arn.split(":");
  if (parts[0] !== "arn") return null;
  const accountId = parts[4];
  if (accountId === undefined || !/^[0-9]{12}$/.test(accountId)) return null;
  return accountId;
}

This splits the ARN on colons, checks that the first component is "arn", and returns the fifth component only if it is exactly 12 ASCII digits. Otherwise it returns null, and the remaining components are not validated.
